'use client';
import React from 'react';
import type {RecordRow as R} from '@/lib/erp-primitives';
import {rockProgress,rockSummary,bidRadar} from '@/lib/leadership';
const fmt=(n:number)=>new Intl.NumberFormat('en-UG',{maximumFractionDigits:1}).format(n);
export function RockProgress({rock}:{rock:Pick<R,'status'>&{progress?:unknown}}){const v=rockProgress(rock);return <div className="rockprogress">{v===null?<span>Progress not recorded</span>:<><progress value={v} max={100} aria-label="Recorded Rock progress"/><span>{fmt(v)}% recorded</span></>}</div>;}
export function RockOverview({rocks}:{rocks:R[]}){const s=rockSummary(rocks);return <div className="rockoverview"><div><small>Completed Rocks</small><strong>{s.done} / {s.total}</strong></div><div><small>On track</small><strong>{s.onTrack}</strong></div><div><small>At risk</small><strong>{s.atRisk}</strong></div><div><small>Average recorded progress</small><strong>{s.average===null?'Not recorded':fmt(s.average)+'%'}</strong><small>{s.recorded} of {s.total} Rocks with progress</small></div><p>Progress is entered manually. Completed Rocks count as 100 percent. Status and percentage remain separate measures.</p></div>;}
export function TenderRadar({records,company,date,office=false,onOpen}:{records:R[];company:string;date:string;office?:boolean;onOpen?:(id:string)=>void}){const rows=bidRadar(records,company,date,office);return <div className="tenderradar">{rows.slice(0,6).map(r=><article key={r.id}><div><small>{r.company} · {r.status}</small>{onOpen?<button className="rowlink" onClick={()=>onOpen(r.id)}><strong>{r.title}</strong></button>:<h4>{r.title}</h4>}<small>Deadline {r.due}</small></div><span>{r.days<0?'Deadline passed':r.days===0?'Due today':r.days<=7?'Due within 7 days':r.days+' days remaining'}</span></article>)}{!rows.length&&<p className={office?'wallempty':'empty'}>{office?'No bid deadlines selected for office display.':'No open bids with deadlines recorded.'}</p>}<p className={office?'wallcaption':'footnote'}>{rows.length>6?'Showing the first 6 of '+rows.length+' deadlines. ':''}Recorded opportunities through {date}. Confirm deadlines against the buyer notice. External tender feeds are awaiting setup.</p></div>;}
